// Bridge from care-team/ to the ElderActor (actor/, P1).
//
// "terse":   uses the typed client generated by `terse actor generate` into care-team/generated/.
// "console": records calls in memory and prints them. Used until the actor is up, and in tests.
// "auto":    terse when care-team/generated/ exists, else console.

import type { Config } from "./config.ts"
import type { LogEventInput, Status } from "./types.ts"

export interface ActorPort {
  logEvent(e: LogEventInput): Promise<unknown>
  setStatus(status: Status, reason: string): Promise<unknown>
  scheduleCheckIn(atMs: number, reason?: string): Promise<unknown>
}

export interface ActorDirectory {
  readonly mode: "terse" | "console"
  forElder(elderId: string): ActorPort
}

export type RecordedCall =
  | { elderId: string; method: "logEvent"; args: [LogEventInput] }
  | { elderId: string; method: "setStatus"; args: [Status, string] }
  | { elderId: string; method: "scheduleCheckIn"; args: [number, string | undefined] }

/** In-memory actor stand-in. Keeps every call so tests and GET /debug/actor can inspect it. */
export class RecordingActors implements ActorDirectory {
  readonly mode = "console" as const
  readonly calls: RecordedCall[] = []
  constructor(private readonly quiet = false) {}

  forElder(elderId: string): ActorPort {
    const push = (c: RecordedCall) => {
      this.calls.push(c)
      if (this.calls.length > 500) this.calls.shift()
      if (!this.quiet) console.log(`[actor:console] ${elderId}.${c.method}`, JSON.stringify(c.args))
    }
    return {
      logEvent: async (e) => push({ elderId, method: "logEvent", args: [e] }),
      setStatus: async (s, r) => push({ elderId, method: "setStatus", args: [s, r] }),
      scheduleCheckIn: async (at, r) => push({ elderId, method: "scheduleCheckIn", args: [at, r] }),
    }
  }
}

/** Retries actor calls so a restart of `terse actor dev` (the durability demo) does not drop Care Feed events. */
function withRetry(port: ActorPort, label: string): ActorPort {
  const wrap = <A extends unknown[]>(name: keyof ActorPort, fn: (...a: A) => Promise<unknown>) =>
    async (...args: A) => {
      let lastErr: unknown
      for (let attempt = 0; attempt < 5; attempt++) {
        try {
          return await fn(...args)
        } catch (err) {
          lastErr = err
          await Bun.sleep(400 * 2 ** attempt)
        }
      }
      console.error(`[actor:terse] ${label}.${name} failed after retries: ${String(lastErr)}`)
      return undefined
    }
  return {
    logEvent: wrap("logEvent", port.logEvent.bind(port)),
    setStatus: wrap("setStatus", port.setStatus.bind(port)),
    scheduleCheckIn: wrap("scheduleCheckIn", port.scheduleCheckIn.bind(port)),
  }
}

class TerseActors implements ActorDirectory {
  readonly mode = "terse" as const
  private cache = new Map<string, ActorPort>()
  constructor(private readonly elderActor: { get(id: string): ActorPort }) {}
  forElder(elderId: string): ActorPort {
    let port = this.cache.get(elderId)
    if (!port) {
      port = withRetry(this.elderActor.get(elderId), elderId)
      this.cache.set(elderId, port)
    }
    return port
  }
}

export async function createActors(config: Config): Promise<ActorDirectory> {
  if (config.actorMode === "console") return new RecordingActors()
  const entry = new URL("../generated/index.js", import.meta.url).pathname
  try {
    const mod = await import(entry)
    const elderActor = mod.actors?.ElderActor ?? mod.ElderActor
    if (!elderActor || typeof elderActor.get !== "function") {
      throw new Error("generated client has no actors.ElderActor.get(id)")
    }
    return new TerseActors(elderActor)
  } catch (err) {
    if (config.actorMode === "terse") throw new Error(`ACTOR_MODE=terse but the generated client failed to load: ${String(err)}`)
    console.warn(`[actor] generated client not found (${String(err).slice(0, 120)}). Using the console actor. Run \`terse actor generate\` in care-team/ once actor/ is running.`)
    return new RecordingActors()
  }
}
